(()=>{const addCss=()=>{[['navigation-v2-css','/assets/css/navigation-v2.css?v=3'],['approche-frise-v2-css','/assets/css/approche-frise-v2.css?v=3']].forEach(([id,href])=>{if(document.getElementById(id)||document.querySelector(`link[href*="${href.split('?')[0]}"]`))return;const l=document.createElement('link');l.id=id;l.rel='stylesheet';l.href=href;document.head.appendChild(l)})};const load=src=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.defer=true;s.onload=resolve;s.onerror=reject;document.head.appendChild(s)});const mount=()=>{const old=document.querySelector('.nav');if(!old||document.getElementById('site-header'))return;old.outerHTML=`<header class="site-header" id="site-header"><a class="site-header__brand" href="#main" aria-label="Paranoir Studio, retour en haut">Paranoir Studio</a><nav class="site-header__nav" aria-label="Navigation principale"><div class="site-header__links"><a class="site-header__link" href="#approche">Approche</a><a class="site-header__link" href="#diagnostic">Diagnostic</a><a class="site-header__link" href="#projets">Offres</a><a class="site-header__link" href="#realisations">Réalisations</a><a class="site-header__link" href="#avis">Avis</a><a class="site-header__link" href="#studio">Studio</a><a class="site-header__link" href="#faq">FAQ</a></div></nav><div class="site-header__actions"><button class="site-header__intent" type="button" data-open-intent aria-expanded="false" aria-controls="intent-modal">Vous voulez ?</button><a class="site-header__cta" href="#diagnostic">Diagnostic gratuit</a><button class="site-header__menu-toggle" id="menuToggle" type="button" aria-label="Ouvrir le menu" aria-expanded="false" aria-controls="mobileMenu"><span></span><span></span><span></span></button></div></header>`;const page=document.querySelector('.page');const main=document.getElementById('main');if(!page||!main)return;const backdrop=document.createElement('div');backdrop.className='site-mobile-menu__backdrop';backdrop.id='mobileMenuBackdrop';page.insertBefore(backdrop,main);const mobile=document.createElement('aside');mobile.className='site-mobile-menu';mobile.id='mobileMenu';mobile.setAttribute('aria-label','Menu mobile');mobile.innerHTML=`<nav class="site-mobile-menu__links"><a href="#approche">Approche</a><a href="#diagnostic">Diagnostic</a><a href="#projets">Offres</a><a href="#realisations">Réalisations</a><a href="#avis">Avis</a><a href="#studio">Studio</a><a href="#faq">FAQ</a></nav><div class="site-mobile-menu__actions"><button class="site-header__intent" type="button" data-open-intent aria-expanded="false" aria-controls="intent-modal">Vous voulez ?</button><a class="site-header__cta" href="#diagnostic">Diagnostic gratuit</a></div>`;page.insertBefore(mobile,main);const dlg=document.createElement('dialog');dlg.className='intent-modal';dlg.id='intent-modal';dlg.setAttribute('aria-labelledby','intent-modal-title');dlg.innerHTML=`<div class="intent-modal__inner"><div class="intent-modal__top"><div><p class="intent-modal__eyebrow">Choisissez votre point d’entrée</p><h2 id="intent-modal-title">Vous voulez quoi, exactement ?</h2><p class="intent-modal__intro">Choisissez la manière la plus simple de commencer avec Paranoir.</p></div><button class="intent-modal__close" id="intentModalClose" type="button" aria-label="Fermer la fenêtre">×</button></div><div class="intent-modal__options"><a class="intent-option" href="#diagnostic"><span class="intent-option__num">01</span><h3>Clarifier et déployer</h3><p>Commencer par le diagnostic, clarifier votre stratégie puis la déployer sur le site, le réseau social principal et la fiche Google.</p><span class="intent-option__arrow" aria-hidden="true">→</span></a><a class="intent-option" href="/formation"><span class="intent-option__num">02</span><h3>Former votre équipe</h3><p>Transmettre une méthode claire pour structurer les messages et la communication en interne.</p><span class="intent-option__arrow" aria-hidden="true">→</span></a><a class="intent-option" href="https://wa.me/33637432180?text=Bonjour%20Paranoir%2C%20je%20souhaite%20vous%20parler%20de%20mon%20projet." target="_blank" rel="noopener noreferrer"><span class="intent-option__num">03</span><h3>Parler de votre projet</h3><p>Vous avez une situation particulière ou vous préférez échanger directement avec nous sur WhatsApp.</p><span class="intent-option__arrow" aria-hidden="true">→</span></a></div></div>`;document.body.appendChild(dlg)};addCss();if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();load('/assets/js/site.js?v=6').then(()=>load('/assets/js/navigation-v2.js?v=4')).then(()=>load('/assets/js/hero-deployment-v2.js?v=6')).catch(console.error)})();